(function () {
  'use strict';
  const p5 = window.p5;

  let sketch = null;

  function setup() {
    sketch = new p5(sketch, sketch, sketch, sketch, sketch);
  }

  function draw() {
    sketch.background(40);
    sketch.line(0, 0, 200, 400);
    sketch.fill(254, 254, 173, 0.45);
    sketch.beginShape();
    sketch.vertex(100, 400);
    sketch.vertex(200, 350);
    sketch.vertex(300, 300);
    sketch.vertex(350, 350);
    sketch.vertex(400, 400);
    sketch.endShape();
    sketch.noStroke();
    sketch.fill(0, 128, 128, 0.5);
    sketch.beginShape();
    sketch.vertex(100, 400);
    sketch.vertex(150, 350);
    sketch.vertex(170, 300);
    sketch.vertex(200, 300);
    sketch.vertex(250, 350);
    sketch.endShape();
    sketch.stroke(255, 0, 0);
    sketch.text("Explore", 200, 390);
    sketch.fill(255, 0, 0);
    sketch.stroke();
    sketch.translate(-width / 2, -height / 2);
    sketch.background("#e08a72");
  }

  // Function to draw the brush strokes
  function drawStrokes() {
    sketch.fill('blue', 45);
    sketch.stroke('blue');
    sketch.noFill();
    sketch.stroke('white');
    sketch.strokeWeight(2);
    sketch.beginPath();
    sketch.moveTo(0, 0);
    sketch.lineTo(300, 0);
    sketch.strokeWeight(1);
    sketch.closePath();
  }
})();
